#!/usr/bin/env python3
# ---------------------------------------------------------------------------
# pocket-voxel patcher: Viridian old-man CATCH DEMO battle (patcher 2 of 2)
# Requires patcher 1 (apply_viridian_oldman_1.py) applied first.  TS-only, no
# cargo.
#
# Ports the BATTLE_TYPE_OLD_MAN tutorial from ~/gen1recomp:
#   * BattleState.makeOldManDemo (:806-835) + oldManThrow (:2197-2210): the old
#     man throws one POKe BALL at a wild WEEDLE, always catches (Red/Blue), and
#     KEEPS NOTHING -- no party add, no dex mark, no ball consumed.
#   * the demo drive (:1858-1870): no player input; the menu hover leads into
#     the throw.  enter() sends out no player mon; the player side stays hidden.
#   * game/overworld startOldManDemo: the old_man_demo opcode hand-off, wired
#     like start_battle (onDone resumes the map script).
#
# Idempotent; aborts if an anchor is missing/ambiguous (patcher 1 not applied,
# or wrong tree).  Run from ~/pocket-voxel:  python3 apply_viridian_oldman_2.py
# ---------------------------------------------------------------------------
import base64, sys, os
HUNKS = [{'path': 'voxelmon/game/battle/battle.ts', 'old': '', 'new': ''}, {'path': 'voxelmon/game/battle/battle.ts', 'old': '', 'new': ''}, {'path': 'voxelmon/game/battle/battle.ts', 'old': '', 'new': ''}, {'path': 'voxelmon/game/battle/battle.ts', 'old': '', 'new': ''}, {'path': 'voxelmon/game/battle/battle.ts', 'old': '', 'new': ''}, {'path': 'voxelmon/game/game.ts', 'old': 'ICAgIHN0Lmxvc2VhYmxlID0gbG9zZWFibGU7CiAgICB0aGlzLnB1c2goc3QpOwogIH0KCiAgbmFtaW5nKCk6IHsgdmlldygpOiBhbnkgfSB8IG51bGwgewogICAgY29uc3QgdG9wID0gdGhpcy5zdGFja1t0aGlzLnN0YWNrLmxlbmd0aCAtIDFdIGFzIGFueTsKICAgIHJldHVybiB0b3A/LmtpbmQgPT09ICJuYW1pbmciID8gdG9wIDogbnVsbDsKICB9Cg==', 'new': ''}, {'path': 'voxelmon/game/world/overworld.ts', 'old': '', 'new': ''}]
def main():
    root=os.getcwd()
    if not os.path.isdir(os.path.join(root,"voxelmon")):
        sys.exit("! run this from the pocket-voxel repo root (no ./voxelmon here)")
    changed=skipped=0; by_file={}
    for h in HUNKS: by_file.setdefault(h["path"],[]).append(h)
    for path,hs in by_file.items():
        fp=os.path.join(root,path)
        if not os.path.isfile(fp): sys.exit(f"! missing file: {path}")
        text=open(fp,encoding="utf-8").read(); orig=text
        for h in hs:
            old=base64.b64decode(h["old"]).decode(); new=base64.b64decode(h["new"]).decode()
            if new in text: skipped+=1; continue
            n=text.count(old)
            if n==0:
                sys.exit(f"! anchor not found in {path}\n  (apply patcher 1 first, or this is not the expected tree)")
            if n>1:
                sys.exit(f"! anchor is ambiguous in {path} ({n} matches) -- aborting")
            text=text.replace(old,new,1); changed+=1
        if text!=orig:
            open(fp,"w",encoding="utf-8").write(text); print(f"  patched {path}")
    print(f"done: {changed} hunk(s) applied, {skipped} already present")
    if changed==0 and skipped: print("(nothing to do -- patcher already applied)")
if __name__=="__main__": main()
